import{_ as e,c as r,o as p,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"14、【大有】 乾下離上","description":"周易尚氏學 - 14、【大有】 乾下離上","frontmatter":{"title":"14、【大有】 乾下離上","description":"周易尚氏學 - 14、【大有】 乾下離上"},"headers":[],"relativePath":"classics/shangshi/019.md","filePath":"classics/shangshi/019.md"}'),s={name:"classics/shangshi/019.md"};function t(h,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_14、【大有】-乾下離上" tabindex="-1">14、【大有】 乾下離上 <a class="header-anchor" href="#_14、【大有】-乾下離上" aria-label="Permalink to “14、【大有】 乾下離上”">​</a></h1><p>離乾皆居南。故曰大有。與同人義同也。元亨謂五也。五得尊位。故曰元。上下應故曰亨。坤五曰元吉。比五曰元永貞。損五益五鼎五。皆曰元吉。是其證。</p><p>彖曰。大有柔得尊位。大中而上下應之。曰大有。其德剛健而文明。應乎天而時行，是以元亨。</p><p>五天位二應之。故曰應乎天。離為夏。萬物相見。故曰時行。</p><p>象曰。火在天上。大有。君子以遏惡揚善。順天休命。</p><p>離為惡人。乾為善。二五相應予。而皆不當位。九二雲。有攸往。是二必往五也。二往五是揚善也。二往五則五下居二。是遏惡也。乾為天為命。陰承乾。故曰順天休命。休。美也。</p><p>初九。無交害。匪咎。艱則無咎。</p><p>初無應。陽遇陽失類。故無交。無交故無害。然須艱貞自守。方無咎也。</p><h3 id="象曰。大有初九。無交害也。" tabindex="-1">象曰。大有初九。無交害也。 <a class="header-anchor" href="#象曰。大有初九。無交害也。" aria-label="Permalink to “象曰。大有初九。無交害也。”">​</a></h3><p>九二。大車以載。有攸往。無咎。</p><p>伏坤為大車為載。按考工記。車人。大車。牛車也。兩轅。牛在轅內。凡載物皆用大車。與馬車回異。馬車皆小車。一轅。兩服在左右。專備人乘。若載物必大車也。故曰大車以載。上有應。往則得位。故無咎。</p><h3 id="象曰。大車以載。積中不敗也。" tabindex="-1">象曰。大車以載。積中不敗也。 <a class="header-anchor" href="#象曰。大車以載。積中不敗也。" aria-label="Permalink to “象曰。大車以載。積中不敗也。”">​</a></h3><p>二得中。承乘皆陽。皆曰積中。乾為實。故為積也。陽上升。故曰大車以載。義則本爻。象則用伏。(廬氏以乾為大車。乾似無此象。)</p><p>九三。公用亨於天子。小人弗克。</p><p>三為三公。兌為亨。天子謂五。小人謂四。四不中不正。失位無應。故曰小人。三兌體。可受亨於五。然而弗能者。以四亦陽害之也。</p><h3 id="象曰。公用亨於天子。小人害也。" tabindex="-1">象曰。公用亨於天子。小人害也。 <a class="header-anchor" href="#象曰。公用亨於天子。小人害也。" aria-label="Permalink to “象曰。公用亨於天子。小人害也。”">​</a></h3><p>九四。匪其彭。無咎。</p><p>釋文雲。彭。子夏傳作旁。虞作尪。雲作彭作旁。聲字之誤。王陶廬雲。諸家易俱不作尪。此仲翔故生異說。與先儒為難。按說文雲。彭。鼓聲也。釋名彭旁也。然則彭之旁。音義並同。詩魯頌以車彭彭。毛傳。有力有容也。齊風。行人彭彭。毛傳多也。集韻雲。強盛也。然則彭之義。為聲容盛大無疑。兌為剛魯。故曰彭。離為文。故曰匪。考工記。且其匪色。注。匪採貌也。少儀。車馬之美。匪匪翼翼。注。行而有文也。匪其彭者。言文采之盛大顯著也。</p><h3 id="象曰。匪其彭無咎。明辨皙也。" tabindex="-1">象曰。匪其彭無咎。明辨皙也。 <a class="header-anchor" href="#象曰。匪其彭無咎。明辨皙也。" aria-label="Permalink to “象曰。匪其彭無咎。明辨皙也。”">​</a></h3><p>明辨皙即釋文盛之義。蓋離為嘉會為禮。有禮則有文。上下秩然。明辨以哲。故無咎也。</p><p>六五。厥孚交如。威如。吉。</p><p>孚。信也。五陽全孚於五。故曰交如。離南面嚮明而治。故曰威如。</p><h3 id="象曰。厥孚交如。信以發志也。威如之吉。易而無備也。" tabindex="-1">象曰。厥孚交如。信以發志也。威如之吉。易而無備也。 <a class="header-anchor" href="#象曰。厥孚交如。信以發志也。威如之吉。易而無備也。" aria-label="Permalink to “象曰。厥孚交如。信以發志也。威如之吉。易而無備也。”">​</a></h3><p>五孚於諸陽。得行其志。孚即信。故曰信以發志。伏坎為信為志也。居尊位。人皆敬之。左右咸宜。故不必有所戒備。</p><p>上九。自天佑之。吉無不利。</p><p>五天位。佑助也。王弼雲。餘爻皆乘剛。上獨履柔。故吉利也。</p><h3 id="象曰。大有上吉。自天佑也。" tabindex="-1">象曰。大有上吉。自天佑也。 <a class="header-anchor" href="#象曰。大有上吉。自天佑也。" aria-label="Permalink to “象曰。大有上吉。自天佑也。”">​</a></h3>',27)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
